const serviceKey = 'sb_secret_b0IcObDVlfwIlKpClSJD_Q_bAAK8DxJ';

// 1. LẤY GIÁ NIÊM YẾT CHUẨN TỪ WEBSITE (Chỉ lấy tên món và giá tiền, tuyệt đối KHÔNG lấy ảnh catalog website)
let products = [];
try {
  const res = await fetch('https://bnblofcypxfydnptazrs.supabase.co/rest/v1/products?category_id=eq.1a111111-1111-1111-1111-111111111111&is_available=eq.true&select=name_vi,price', {
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey }
  });
  products = await res.json();
} catch (e) {}

if (!products || !products.length) {
  products = [
    { name_vi: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI", price: 55000 },
    { name_vi: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI", price: 70000 },
    { name_vi: "SANDWICH TRỨNG PHÔ MAI", price: 40000 },
    { name_vi: "SANDWICH DĂM BÔNG PHÔ MAI MỸ", price: 50000 },
    { name_vi: "SANDWICH GÀ NƯỚNG PESTO", price: 60000 },
    { name_vi: "SANDWICH THỊT HỘP, PHÔ MAI & NORI", price: 60000 },
    { name_vi: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI", price: 50000 },
    { name_vi: "SANDWICH CÁ NGỪ PHÔ MAI", price: 60000 },
    { name_vi: "SANDWICH NƯỚNG KIỂU PHÁP", price: 55000 }
  ];
}

// 2. KHO ẢNH THẬT 100% TỪ MẠNG XÃ HỘI (ẢNH ĐỜI THỰC TĨNH CHỤP TẠI BÀN, CẦM TAY DẠO PHỐ, BACKGROUND TỰ NHIÊN)
// Tuyệt đối KHÔNG CẮT TỪ VIDEO TIKTOK, KHÔNG DÙNG ẢNH NỀN TRẮNG CATALOG
const realSocialPhotos = [
  {
    source: "Threads",
    sourceHandle: "@hhnh_7410",
    dishName: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-hero-bacon.jpg"
  },
  {
    source: "Instagram",
    sourceHandle: "@eggu_sandwich",
    dishName: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-story-beef.jpg"
  },
  {
    source: "Threads",
    sourceHandle: "@linhchi_walk",
    dishName: "SANDWICH DĂM BÔNG PHÔ MAI MỸ",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-handheld-crispy.jpg"
  },
  {
    source: "Facebook",
    sourceHandle: "EGGU Fanpage",
    dishName: "SANDWICH TRỨNG PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-egg-cheese-pull.jpg"
  },
  {
    source: "Threads",
    sourceHandle: "@hanoifoodie_eat",
    dishName: "SANDWICH CÁ NGỪ PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-cafe-table.jpg"
  },
  {
    source: "Instagram",
    sourceHandle: "@eggu_sandwich",
    dishName: "SANDWICH THỊT HỘP, PHÔ MAI & NORI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-combo-spread.jpg"
  },
  {
    source: "Threads",
    sourceHandle: "@vietnam_streetwalk",
    dishName: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-bacon-garlic.jpg"
  },
  {
    source: "Facebook",
    sourceHandle: "EGGU Fanpage",
    dishName: "SANDWICH NƯỚNG KIỂU PHÁP",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/promotions/social-real-kitchen-fresh.jpg"
  }
];

// Chọn ngẫu nhiên 1 bức ảnh tĩnh thực tế từ Social
const picked = realSocialPhotos[Math.floor(Math.random() * realSocialPhotos.length)];
const matchedProduct = products.find(p => p.name_vi === picked.dishName) || products[0];

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "";
let suggestedTheme = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  angle = "Đồng hành công sở (Bữa sáng vội vã, ăn sạch tay không dính mỡ, no lâu, gom đơn cùng đồng nghiệp)";
  suggestedTheme = "morning_commute";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  angle = "Cứu đói xế chiều 14h - 16h (Thèm phô mai kéo sợi ngập tràn, tiếp năng lượng giờ làm việc uể oải)";
  suggestedTheme = "street_bold";
} else if (dayOfWeek === 5) {
  angle = "Nạp năng lượng cuối tuần (Tự thưởng cho bản thân bữa ăn nóng hổi chất lượng chuẩn vị Seoul)";
  suggestedTheme = "seoul_cafe";
} else {
  angle = "Dạo phố cổ Hồ Gươm (Bánh nướng nóng hổi cầm tay dạo quanh phố 54 Nguyễn Hữu Huân)";
  suggestedTheme = "hanoi_vintage";
}

const formattedPrice = Number(matchedProduct.price).toLocaleString('vi-VN') + 'đ';

return [
  {
    json: {
      dishName: matchedProduct.name_vi,
      dishPrice: formattedPrice,
      dishPriceRaw: matchedProduct.price,
      photoUrl: picked.photoUrl,
      socialSource: picked.source,
      sourceHandle: picked.sourceHandle,
      photoTag: picked.source + ' (' + picked.sourceHandle + ')',
      targetAngle: angle,
      suggestedTheme: suggestedTheme,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "https://eggusandwich.id.vn/",
      tiktok: "https://www.tiktok.com/@eggu_sandwich?_r=1&_t=ZS-9AH0avwHF7l",
      hotline: "0356 779 899",
      hours: "07:00 – 21:00"
    }
  }
];

// 1. Trích xuất text: Ưu tiên AI Editor, tự động fallback sang AI Writer nếu AI Editor gặp lỗi 503
let rawText = '';
if ($json.content && Array.isArray($json.content.parts)) {
  rawText = $json.content.parts.map(p => p.text || '').join('');
} else if (typeof $json.text === 'string') {
  rawText = $json.text;
} else if (typeof $json.content === 'string') {
  rawText = $json.content;
}

// Fallback sang AI Writer nếu AI Editor bị lỗi
if (!rawText || $json.error) {
  try {
    const writerNode = $('AI Writer (Gemini - Viết Nháp FB & Đạo Diễn Poster)');
    if (writerNode && writerNode.item && writerNode.item.json) {
      const wJson = writerNode.item.json;
      if (wJson.content && Array.isArray(wJson.content.parts)) {
        rawText = wJson.content.parts.map(p => p.text || '').join('');
      } else if (typeof wJson.text === 'string') {
        rawText = wJson.text;
      } else if (typeof wJson.content === 'string') {
        rawText = wJson.content;
      }
    }
  } catch (e) {}
}

rawText = (rawText || '').trim();

// Bỏ markdown code block wrapper ```json ... ```
let cleanText = rawText.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/i, '').trim();

const dishInfo = $('Code - Lấy Ảnh Thật Từ Social (FB, IG, Threads)').item.json;

const exactFooter = `🥪Tiktok: https://www.tiktok.com/@eggu_sandwich?_r=1&_t=ZS-9AH0avwHF7l\n👉Website: https://eggusandwich.id.vn/\n📍 54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội\n🛵 Giao hàng thần tốc trên: Website/ ShopeeFood / Grab / Be / Green / EGets\n📞 0356 779 899\n⏰ 07:00 – 21:00\n#Eggu #SandwichHanQuoc #EggSandwich #FoodInHanoi #newwebsite #anvatHoGuom`;

let parsed = null;
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  const titleM = cleanText.match(/"title"\s*:\s*"([^"]+)"/);
  const contentM = cleanText.match(/"content"\s*:\s*"([\s\S]*?)"\s*,\s*"(?:poster_headline|theme|dish|status)/);
  const headlineM = cleanText.match(/"poster_headline"\s*:\s*"([^"]+)"/);
  const sublineM = cleanText.match(/"poster_subline"\s*:\s*"([^"]+)"/);
  const badgeM = cleanText.match(/"poster_badge"\s*:\s*"([^"]+)"/);
  const themeM = cleanText.match(/"theme"\s*:\s*"([^"]+)"/);

  parsed = {
    title: titleM ? titleM[1] : ('EGGU - ' + dishInfo.dishName),
    content: contentM ? contentM[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') : null,
    poster_headline: headlineM ? headlineM[1] : 'NÓNG HỔI VỪA THỔI VỪA ĂN',
    poster_subline: sublineM ? sublineM[1] : (dishInfo.dishName + ' - Bánh nướng bơ tỏi giòn rụm'),
    poster_badge: badgeM ? badgeM[1] : 'BÁN CHẠY NHẤT',
    theme: themeM ? themeM[1] : (dishInfo.suggestedTheme || 'street_bold')
  };
}

let finalContent = parsed && parsed.content ? parsed.content.trim() : '';

// Nếu không trích được content hợp lệ
if (!finalContent || finalContent.startsWith('{') || finalContent.length < 50) {
  finalContent = `Bắt đầu ngày mới cùng chiếc bánh mì sandwich trứng Hàn Quốc ${dishInfo.dishName} nóng hổi, giòn rụm từ EGGU!\n\nLớp bánh brioche nướng bơ tỏi thơm lừng, ôm trọn phần trứng cuộn fluffy mềm mượt tan chảy cùng phô mai béo ngậy kéo sợi và sốt đặc trưng chuẩn vị Seoul. Từng miếng cắn đậm đà, no lâu mà lại cực kỳ sạch tay, hoàn hảo cho bữa sáng hoặc xế chiều.\n\n👉 Giá niêm yết: ${dishInfo.dishPrice}`;
}

// Chuẩn hóa ĐUÔI BÀI VIẾT (FOOTER) 100% đúng chuẩn theo yêu cầu của tiệm
const bodyOnly = finalContent.split(/🥪Tiktok|👉Website|📍 54 Nguyễn Hữu Huân|#Eggu|#EGGU/)[0].trim();
finalContent = bodyOnly + '\n\n' + exactFooter;

const chosenTheme = (parsed && parsed.theme) || dishInfo.suggestedTheme || 'street_bold';
const headline = (parsed && parsed.poster_headline) || 'NÓNG HỔI VỪA THỔI VỪA ĂN';
const subline = (parsed && parsed.poster_subline) || (dishInfo.dishName + ' - Bánh nướng bơ tỏi giòn rụm');
const badge = (parsed && parsed.poster_badge) || 'BÁN CHẠY NHẤT';

// Link Poster Đồ Họa 1080x1080 sinh ra từ CHÍNH ẢNH THẬT
const posterUrl = 'http://localhost:3000/api/marketing/poster?' +
  'dish=' + encodeURIComponent(dishInfo.dishName) +
  '&price=' + encodeURIComponent(dishInfo.dishPrice) +
  '&headline=' + encodeURIComponent(headline) +
  '&subline=' + encodeURIComponent(subline) +
  '&badge=' + encodeURIComponent(badge) +
  '&theme=' + encodeURIComponent(chosenTheme) +
  '&image=' + encodeURIComponent(dishInfo.photoUrl);

const finalTitle = (parsed && parsed.title) || ('EGGU - ' + dishInfo.dishName);

return [
  {
    json: {
      title: finalTitle,
      dishName: dishInfo.dishName,
      dishCategory: dishInfo.photoTag,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: finalContent,
      realPhotoUrl: dishInfo.photoUrl,
      aiPhotoUrl: posterUrl,
      posterTheme: chosenTheme,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': finalTitle,
      'Món ăn': dishInfo.dishName + ' (Giá web: ' + dishInfo.dishPrice + ')',
      'Nguồn ảnh': dishInfo.photoTag,
      'Nội dung Facebook (Đã biên tập)': finalContent,
      '📸 ẢNH THẬT (Social)': dishInfo.photoUrl,
      '🎨 POSTER ĐỒ HỌA 1080x1080 (AI & Code sinh từ ảnh thật)': posterUrl,
      'Phong cách Poster': chosenTheme,
      'Gợi ý đăng bài': 'Đăng bài kèm ảnh thật hoặc poster đồ họa 1080x1080!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
